import test from 'node:test';
import assert from 'node:assert/strict';
import * as c from '../src/index.js';
import { catalog, copy } from './fixtures.js';
import { simpleChapter, richChapter } from './chapter-fixtures.js';
const build = (chapter = richChapter, extra = {}) => c.buildChapterQuickReview(catalog, chapter, { completedLessonIds: ['lesson.animals'], ...extra });
const session = (chapter = richChapter, extra = {}) => c.createChapterReviewSession(build(chapter), { sessionId: 'review.demo', profileId: 'profile.demo', ...extra });
const begin = state => c.transitionChapterReview(state, { type:'begin' });
const current = state => state.queue[state.cursor];
function response(question, correct = true) {
  if (['choice','context'].includes(question.type)) return correct ? question.correctOptionId : question.options.find(option=>option.id!==question.correctOptionId).id;
  if (question.type==='order') return correct ? question.expectedTokenIds : [...question.expectedTokenIds].reverse();
  return correct ? question.acceptedAnswers[0] : 'not-the-answer';
}
function answer(state, correct = true, overrides = {}) {
  const question=current(state);
  return c.transitionChapterReview(state, { type:'answer',questionId:question.id,response:overrides.response ?? response(question,correct),at:'2026-11-08T02:00:00.000Z',timeZone:'Asia/Ho_Chi_Minh',durationMs:1000,...overrides });
}
const next = state => c.transitionChapterReview(state,{type:'next'});
function finishAll(state, correct=true) { let limit=0; while(state.status==='active' && limit++<30) { state=next(answer(state,correct)); } return state; }

test('chapter validates known lessons and authored items without mutation',()=>{const before=copy(richChapter);assert.equal(c.validateChapter(catalog,before),before);assert.deepEqual(before,richChapter);});
test('chapter rejects unknown lessons and duplicated lesson IDs',()=>{assert.throws(()=>build({...simpleChapter,lessonIds:['missing']}));assert.throws(()=>build({...simpleChapter,lessonIds:['lesson.animals','lesson.animals']}));});
test('chapter rejects authored cards from outside the chapter',()=>{const chapter=copy(richChapter);chapter.reviewItems[0].cardId='color.red';assert.throws(()=>build(chapter),/belong/);});
test('chapter rejects duplicate authored IDs, invalid options and unknown question types',()=>{const chapter=copy(richChapter);chapter.reviewItems[1].id=chapter.reviewItems[0].id;assert.throws(()=>build(chapter));const bad=copy(richChapter);bad.reviewItems[0].correctOptionId='missing';assert.throws(()=>build(bad));bad.reviewItems[0].type='ai-grading';assert.throws(()=>build(bad));});
test('chapter rejects ambiguous context labels',()=>{const chapter=copy(richChapter);chapter.reviewItems[0].options[1].label='cat';assert.throws(()=>build(chapter),/unique/);});
test('chapter rejects invalid sentence-order token sets',()=>{const chapter=copy(richChapter);chapter.reviewItems[1].expectedTokenIds=['i','see','a','missing'];assert.throws(()=>build(chapter),/every token/);});
test('chapter rejects punctuation-only application answers',()=>{const chapter=copy(richChapter);chapter.reviewItems[2].acceptedAnswers=['...'];assert.throws(()=>build(chapter));});
test('chapter readiness lists unfinished lessons separately from review completion',()=>{const r=c.chapterReviewReadiness(catalog,simpleChapter);assert.equal(r.ready,false);assert.deepEqual(r.missingLessonIds,['lesson.animals']);assert.equal(c.chapterReviewReadiness(catalog,simpleChapter,['lesson.animals']).ready,true);});
test('builds five-step chapter review with authored context/order/application',()=>{const plan=build();assert.deepEqual(plan.questions.map(x=>x.type),['choice','choice','context','order','application']);assert.equal(plan.completeFiveStepPattern,true);assert.equal(plan.timed,false);assert.equal(plan.maximumQuestionCount,10);});
test('short chapter without authored content discloses fallback rather than fabricating questions',()=>{const plan=build(simpleChapter);assert.equal(plan.completeFiveStepPattern,false);assert.deepEqual(plan.missingAuthoredTypes,['context','order','application']);assert.equal(plan.questions.length,4);assert.equal(plan.questions[2].type,'recall');});
test('single-card chapter uses recall and never claims a full five-step pattern',()=>{const cat=copy(catalog);cat.lessons[0].cardIds=['animal.dog'];const plan=c.buildChapterQuickReview(cat,simpleChapter,{introducedCardIds:['animal.dog']});assert.equal(plan.questions.length,1);assert.equal(plan.questions[0].type,'recall');assert.equal(plan.completeFiveStepPattern,false);});
test('review question IDs are deterministic and distinct',()=>{assert.deepEqual(build(),build());const plan=build();assert.equal(new Set(plan.questions.map(q=>q.id)).size,plan.questions.length);});
test('prioritizes difficult words within chapter, excludes other chapters',()=>{const r={...c.newReview('animal.fish','2026-11-08'),attempts:3,lapses:2};const outside={...r,cardId:'color.red'};const plan=build(simpleChapter,{reviews:[r,outside]});assert.equal(plan.focusCards[0].cardId,'animal.fish');assert.equal(plan.focusCards[0].reason,'practice-again');assert.ok(plan.questions.every(q=>q.cardId.startsWith('animal.')));});
test('focus cards expose only available audio IDs, never fabricated file references',()=>{assert.ok(build().focusCards.every(card=>card.audioId===null));});
test('review preserves input catalog and review records',()=>{const cat=copy(catalog);const before=copy(cat);c.buildChapterQuickReview(cat,richChapter,{completedLessonIds:['lesson.animals']});assert.deepEqual(cat,before);});
test('end-of-chapter mode requires completed lessons, practice mode stays available',()=>{const plan=c.buildChapterQuickReview(catalog,richChapter,{introducedCardIds:catalog.cards.map(card=>card.id)});assert.throws(()=>c.createChapterReviewSession(plan,{sessionId:'s',profileId:'p'}),/finish the chapter/);assert.equal(c.createChapterReviewSession(plan,{sessionId:'s',profileId:'p',mode:'practice'}).mode,'practice');});
test('session begins with focused recap before questions',()=>{const s=session();assert.equal(s.phase,'focus');assert.equal(c.chapterQuestionView(s).focusCards.length,4);assert.equal(begin(s).phase,'question');});
test('answers before beginning do not score',()=>{const s=session();assert.equal(answer(s),s);assert.equal(s.events.length,0);});
test('question display hides correct-answer fields before feedback',()=>{const s=begin(session());const view=c.chapterQuestionView(s);for(const field of ['correctOptionId','acceptedAnswers','expectedTokenIds','en','vi'])assert.equal(field in view,false);assert.equal(view.hideLearningLabel,true);assert.equal(view.timed,false);});
test('hint records assisted response separately from unassisted first attempts',()=>{let s=begin(session());s=c.transitionChapterReview(s,{type:'hint',questionId:current(s).id});assert.equal(s.hintUsed,true);assert.ok(c.chapterQuestionView(s).hint);s=answer(s);assert.equal(s.attempts[0].usedHint,true);assert.equal(s.events[0].grade,'hard');const summary=c.summarizeChapterReview(s);assert.deepEqual(summary.assistedFirstPass,{answered:1,correct:1});assert.deepEqual(summary.unassistedFirstPass,{answered:0,correct:0});});
test('authored hints are displayed instead of a fabricated hint',()=>{let s=begin(session());s=next(answer(s));s=next(answer(s));s=c.transitionChapterReview(s,{type:'hint',questionId:current(s).id});assert.equal(s.visibleHint,richChapter.reviewItems[0].hint);});
test('hint state resets between questions',()=>{let s=begin(session());s=c.transitionChapterReview(s,{type:'hint',questionId:current(s).id});s=next(answer(s));assert.equal(s.hintUsed,false);assert.equal(s.visibleHint,null);});
test('correct five-question flow completes review and emits compatible events',()=>{const s=finishAll(begin(session()));assert.equal(s.status,'completed');assert.equal(s.result.reviewCompleted,true);assert.equal(s.result.firstPassCorrect,5);assert.equal(s.events.length,5);assert.equal(c.mergeEvents(s.events).length,5);assert.equal(c.chapterQuestionView(s).phase,'summary');});
test('wrong answer schedules one retry at the end and shows explicit answer',()=>{const s=answer(begin(session()),false);assert.equal(s.queue.length,6);assert.equal(s.feedback.retryScheduled,true);assert.ok(s.feedback.answer);assert.ok(s.feedback.explanationVi.includes(s.feedback.answer));assert.equal(s.queue[5].isRetry,true);});
test('retry recovery is separated from first-pass accuracy',()=>{let s=next(answer(begin(session()),false));s=finishAll(s);assert.equal(s.result.firstPassCorrect,4);assert.equal(s.result.firstPassAccuracy,0.8);assert.equal(s.result.totalAttempts,6);assert.equal(s.result.recoveredCardIds.length,1);assert.equal(s.result.practiceAgainCardIds.length,0);});
test('repeated failure has a finite retry cap and never loops indefinitely',()=>{const s=finishAll(begin(session()),false);assert.equal(s.status,'completed');assert.equal(s.queue.length,10);assert.equal(s.attempts.length,10);assert.ok(s.result.practiceAgainCardIds.length>0);assert.equal(s.result.reviewCompleted,true);});
test('final failed retry promises future practice, not an extra nonexistent retry',()=>{let s=begin(session());s=next(answer(s,false));for(let i=0;i<4;i++)s=next(answer(s));s=answer(s,false);assert.equal(s.feedback.retryScheduled,false);assert.ok(s.feedback.messageVi.includes('lần sau'));});
test('duplicate answer clicks create no extra attempt or progress event',()=>{const s=answer(begin(session()));assert.equal(answer(s),s);assert.equal(s.events.length,1);});
test('duplicate next clicks cannot skip a question',()=>{const s=next(answer(begin(session())));assert.equal(next(s),s);assert.equal(s.cursor,1);});
test('stale question answers and hints cannot affect the next question',()=>{const old=begin(session());const s=next(answer(old));assert.throws(()=>answer(s,true,{questionId:current(old).id}),/stale/);assert.throws(()=>c.transitionChapterReview(s,{type:'hint',questionId:current(old).id}),/stale/);});
test('pause and resume preserve question and ignore answers while paused',()=>{const original=begin(session());const paused=c.transitionChapterReview(original,{type:'pause'});assert.equal(answer(paused),paused);assert.equal(c.transitionChapterReview(paused,{type:'resume'}).cursor,0);});
test('pause during feedback preserves existing result',()=>{const answered=answer(begin(session()));const s=c.transitionChapterReview(c.transitionChapterReview(answered,{type:'pause'}),{type:'resume'});assert.equal(s.phase,'feedback');assert.equal(s.events.length,1);});
test('exit never awards completion, and late events become no-ops',()=>{const s=c.transitionChapterReview(answer(begin(session())),{type:'exit'});assert.equal(s.result.reviewCompleted,false);assert.equal(s.result.completionKey,null);assert.equal(answer(s),s);});
test('completed review is immutable under repeated next, exit or answer',()=>{const s=finishAll(begin(session()));assert.equal(next(s),s);assert.equal(c.transitionChapterReview(s,{type:'exit'}),s);assert.equal(answer(s),s);});
test('invalid option IDs and malformed ordering responses fail without mutating state',()=>{const s=begin(session());assert.throws(()=>answer(s,true,{response:'not-an-option'}));let order=s;for(let i=0;i<3;i++)order=next(answer(order));assert.equal(current(order).type,'order');assert.throws(()=>answer(order,true,{response:['i','i','a','dog']}));assert.equal(order.attempts.length,3);});
test('session cannot record timestamps backwards',()=>{const s=next(answer(begin(session())));assert.throws(()=>answer(s,true,{at:'2026-11-08T01:59:59.000Z'}),/nondecreasing/);});
test('feedback defaults to no sound when there is no confirmed audio asset',()=>{assert.equal(c.chapterFeedbackCue({correct:true}).soundCue,null);assert.equal(answer(begin(session())).feedback.soundCue,null);});
test('feedback respects reduced motion and sound settings',()=>{const cue=c.chapterFeedbackCue({correct:true,reducedMotion:true,soundAvailable:true,soundEnabled:false});assert.equal(cue.animation,'none');assert.equal(cue.animationDurationMs,0);assert.equal(cue.soundCue,null);assert.equal(cue.requiresLiveAnnouncement,true);assert.equal(c.chapterFeedbackCue({correct:false,soundAvailable:true}).soundCue,'soft-hint');});
test('unknown actions and invalid settings fail early',()=>{assert.throws(()=>c.transitionChapterReview(session(),{type:'unlock-all'}));assert.throws(()=>c.chapterFeedbackCue({correct:'yes'}));assert.throws(()=>build(richChapter,{questionCount:13}));assert.throws(()=>session(richChapter,{sessionId:'s'.repeat(81)}));});
test('unanswered review summary has no fabricated accuracy or completion',()=>{const r=c.summarizeChapterReview(session());assert.equal(r.firstPassAccuracy,null);assert.equal(r.reviewCompleted,false);assert.equal(r.firstPassAnswered,0);});
test('review never introduces unlearned cards or authored questions for them',()=>{const plan=build(richChapter,{introducedCardIds:['animal.dog','animal.fish']});assert.ok(plan.questions.every(q=>['animal.dog','animal.fish'].includes(q.cardId)));assert.ok(plan.missingAuthoredTypes.includes('context'));assert.ok(plan.missingAuthoredTypes.includes('application'));});
test('review requires introduced-card or completed-lesson evidence',()=>{assert.throws(()=>c.buildChapterQuickReview(catalog,simpleChapter),/introduced cards/);const r={...c.newReview('animal.cat','2026-11-08'),attempts:1};const plan=c.buildChapterQuickReview(catalog,simpleChapter,{reviews:[r]});assert.deepEqual(plan.focusCards.map(card=>card.cardId),['animal.cat']);});
test('snapshot resumes the same unanswered round including visible hint and pause',()=>{let s=next(answer(begin(session())));s=c.transitionChapterReview(s,{type:'hint',questionId:current(s).id});s=c.transitionChapterReview(s,{type:'pause'});const restored=c.restoreChapterReviewSnapshot(c.exportChapterReviewSnapshot(s),s.plan,s.profileId);assert.deepEqual(restored,s);assert.equal(restored.cursor,1);assert.equal(restored.hintUsed,true);assert.equal(restored.status,'paused');});
test('snapshot resumes feedback without duplicating progress events',()=>{const s=answer(begin(session()),false);const restored=c.restoreChapterReviewSnapshot(c.exportChapterReviewSnapshot(s),s.plan,s.profileId);assert.deepEqual(restored,s);assert.equal(restored.events.length,1);assert.equal(restored.queue.length,6);});
test('completed snapshot restores its result and completion key',()=>{const s=finishAll(begin(session()));assert.deepEqual(c.restoreChapterReviewSnapshot(c.exportChapterReviewSnapshot(s),s.plan,s.profileId),s);});
test('snapshot rejects wrong profile, version, changed content and invalid journal',()=>{const s=begin(session());const serialized=c.exportChapterReviewSnapshot(s);assert.throws(()=>c.restoreChapterReviewSnapshot(serialized,s.plan,'other'));const saved=JSON.parse(serialized);saved.schemaVersion=2;assert.throws(()=>c.restoreChapterReviewSnapshot(JSON.stringify(saved),s.plan,s.profileId));const changed=copy(s.plan);changed.title='Changed';assert.throws(()=>c.restoreChapterReviewSnapshot(serialized,changed,s.profileId),/plan changed/);saved.schemaVersion=1;saved.journal.push({type:'begin'});assert.throws(()=>c.restoreChapterReviewSnapshot(JSON.stringify(saved),s.plan,s.profileId),/duplicate transition/);});
test('journal drops unknown action fields and duplicate clicks',()=>{const s=answer(begin(session()),true,{childName:'DO NOT SAVE'});assert.equal('childName' in s.journal.at(-1),false);assert.equal(answer(s).journal.length,s.journal.length);});
test('skip is not an incorrect answer or a practice event',()=>{const s=begin(session());const skipped=c.transitionChapterReview(s,{type:'skip',questionId:current(s).id});assert.equal(skipped.events.length,0);assert.equal(skipped.attempts[0].correct,null);const r=c.summarizeChapterReview(skipped);assert.equal(r.firstPassAnswered,0);assert.equal(r.skippedRounds,1);assert.equal(r.totalAttempts,0);assert.equal(r.deferredCardIds.length,1);});
test('skipping every round permits a neutral finish without invented accuracy',()=>{let s=begin(session());while(s.status==='active')s=next(c.transitionChapterReview(s,{type:'skip',questionId:current(s).id}));assert.equal(s.result.reviewCompleted,true);assert.equal(s.result.firstPassAccuracy,null);assert.equal(s.result.totalAttempts,0);assert.equal(s.result.skippedRounds,5);assert.ok(s.result.messageVi.includes('kết thúc'));});
test('wrong question then skipped retry remains both deferred and needing practice',()=>{let s=next(answer(begin(session()),false));for(let i=0;i<4;i++)s=next(answer(s));const failedCard=current(s).cardId;s=next(c.transitionChapterReview(s,{type:'skip',questionId:current(s).id}));assert.ok(s.result.practiceAgainCardIds.includes(failedCard));assert.ok(s.result.deferredCardIds.includes(failedCard));});
function adultSession(){const chapter=copy(richChapter);chapter.reviewItems[2]={...chapter.reviewItems[2],assessment:'adult_observation',prompt:'Em nói một câu về con chim, hoặc chỉ ảnh cùng người lớn.'};delete chapter.reviewItems[2].acceptedAnswers;let s=begin(session(chapter));for(let i=0;i<4;i++)s=next(answer(s));return s;}
test('open/spoken task accepts adult observation without automatic scoring or mic requirement',()=>{const s=adultSession();assert.equal(c.chapterQuestionView(s).assessment,'adult_observation');assert.throws(()=>answer(s,true,{response:'I see a bird'}),/adult observation/);const observed=c.transitionChapterReview(s,{type:'observe',questionId:current(s).id,observation:'supported'});assert.equal(observed.events.length,4);assert.equal(observed.attempts[4].assessed,false);assert.equal(c.summarizeChapterReview(observed).observations[0].observation,'supported');});
test('adult observation cannot be used to score an exact question',()=>{const s=begin(session());assert.throws(()=>c.transitionChapterReview(s,{type:'observe',questionId:current(s).id,observation:'independent'}));});
test('application requires explicit scoring policy and observation has no exact key',()=>{const chapter=copy(richChapter);delete chapter.reviewItems[2].assessment;assert.throws(()=>build(chapter),/explicitly/);chapter.reviewItems[2].assessment='adult_observation';assert.throws(()=>build(chapter),/exact-answer/);});
test('skipped or observed final round restores from snapshot without adding practice events',()=>{const s=adultSession();const finished=next(c.transitionChapterReview(s,{type:'observe',questionId:current(s).id,observation:'defer'}));const restored=c.restoreChapterReviewSnapshot(c.exportChapterReviewSnapshot(finished),finished.plan,finished.profileId);assert.deepEqual(restored,finished);assert.equal(restored.events.length,4);assert.equal(restored.result.observations[0].observation,'defer');});
test('same-round resume can rebuild original plan from content after process restart',()=>{const s=next(answer(begin(session()),false));const serialized=c.exportChapterReviewSnapshot(s);const restored=c.restoreChapterReviewFromContent(serialized,catalog,richChapter,s.profileId);assert.deepEqual(restored,s);assert.equal(restored.queue.length,6);});
test('content-based restore rejects tampered recipe and changed lesson data',()=>{const s=begin(session());const data=JSON.parse(c.exportChapterReviewSnapshot(s));data.recipe.seed='changed';assert.throws(()=>c.restoreChapterReviewFromContent(JSON.stringify(data),catalog,richChapter,s.profileId),/plan changed/);const changed=copy(catalog);changed.cards[0].vi='changed';assert.throws(()=>c.restoreChapterReviewFromContent(c.exportChapterReviewSnapshot(s),changed,richChapter,s.profileId));});
